import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.nio.file.Path;

public class ConfigReader {
    public String readConfig(Path configPath) throws IOException {
        // BufferedReader is AutoCloseable - will be closed automatically
        try (BufferedReader reader = new BufferedReader(new FileReader(configPath.toFile()))) {
            var config = new StringBuilder();
            String line;
            // Read all lines from config file
            while ((line = reader.readLine()) != null) {
                config.append(line).append("\n");
            }
            return config.toString();
        } // reader.close() called here automatically, even if exception occurs
    }
}

import javax.sql.DataSource;
import java.sql.Connection;
import java.sql.SQLException;

public class DatabaseTransaction implements AutoCloseable {
    private final Connection connection;
    private boolean committed = false;

    public DatabaseTransaction(DataSource dataSource) throws SQLException {
        this.connection = dataSource.getConnection();
        this.connection.setAutoCommit(false); // Start transaction
    }

    public Connection getConnection() {
        return connection;
    }

    public void commit() throws SQLException {
        connection.commit();
        committed = true;
    }

    @Override
    public void close() throws SQLException {
        try {
            if (!committed) {
                connection.rollback(); // Rollback if not explicitly committed
            }
        } finally {
            connection.close(); // Always close the connection
        }
    }
}

// Usage: automatic rollback if exception occurs
try (var tx = new DatabaseTransaction(dataSource)) {
    var stmt = tx.getConnection().prepareStatement("INSERT INTO orders...");
    stmt.executeUpdate();
    tx.commit(); // Explicit commit on success
} // Auto-rollback if exception thrown before commit

import java.io.*;
import java.nio.file.Path;
import java.sql.*;

public class MultiResourceExample {

    // Example 1: Database connection and statement
    public void updateDatabase(String url, String sql) throws SQLException {
        try (Connection conn = DriverManager.getConnection(url);
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.executeUpdate();
            // stmt closes first, then conn - proper order
        }
    }

    // Example 2: Nested streams for buffered file writing
    public void writeLog(Path logPath, String message) throws IOException {
        try (FileWriter fileWriter = new FileWriter(logPath.toFile());
             BufferedWriter bufferedWriter = new BufferedWriter(fileWriter)) {
            bufferedWriter.write(message);
            bufferedWriter.newLine();
            // bufferedWriter closes first (flushes buffer), then fileWriter
        }
    }

    // Example 3: Reading and writing simultaneously
    public void copyFile(Path source, Path dest) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(source.toFile()));
             BufferedWriter writer = new BufferedWriter(new FileWriter(dest.toFile()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                writer.write(line);
                writer.newLine();
            }
            // writer closes first, then reader - independent resources
        }
    }
}

import java.io.*;
import java.nio.file.Path;

public class Java9TryWithResources {

    // Java 9+: Use existing effectively final variable
    public void processStream(InputStream input) throws IOException {
        // input is effectively final (method parameter)
        try (input) { // No need to redeclare: try (InputStream in = input)
            var data = input.readAllBytes();
            System.out.println("Read " + data.length + " bytes");
        } // input.close() called automatically
    }

    // Multiple existing variables
    public void copyWithExisting(Path source, Path dest) throws IOException {
        var reader = new BufferedReader(new FileReader(source.toFile()));
        var writer = new BufferedWriter(new FileWriter(dest.toFile()));

        // Both reader and writer are effectively final
        try (reader; writer) { // Semicolon separator for multiple resources
            String line;
            while ((line = reader.readLine()) != null) {
                writer.write(line);
                writer.newLine();
            }
        }
    }

    // Java 7-8 required: must redeclare even if variable exists
    public void oldStyle(InputStream input) throws IOException {
        try (InputStream in = input) { // Duplication required pre-Java-9
            var data = in.readAllBytes();
        }
    }
}
